# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">OSMANLI DEVLETİ\'Nİ CİHAN DEVLETİ YAPAN TEMEL POLİTİKALAR (SB.7.3.1)</text>\n  <rect x="22" y="48" width="155" height="190" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="99" y="72" text-anchor="middle" font-size="12" font-weight="bold" fill="#1d4ed8">1. Gaza ve Cihat</text>\n  <text x="34" y="96" font-size="10.5" fill="#334155">• İslam dinini koruma ve</text>\n  <text x="34" y="112" font-size="10.5" fill="#334155">  adaleti dünyaya yayma</text>\n  <text x="34" y="128" font-size="10.5" fill="#334155">  amacıyla yapılan fetihler</text>\n  <text x="34" y="152" font-size="10.5" fill="#334155">• Anadolu gazilerinin ve</text>\n  <text x="34" y="168" font-size="10.5" fill="#334155">  alperenlerin desteğini</text>\n  <text x="34" y="184" font-size="10.5" fill="#334155">  kazandırmıştır</text>\n  <text x="99" y="216" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#1e40af">Fetih Ruhu ve İ\'lâ-yı Kelimetullah</text>\n  <rect x="188" y="48" width="155" height="190" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="265" y="72" text-anchor="middle" font-size="12" font-weight="bold" fill="#15803d">2. İstimalet (Hoşgörü)</text>\n  <text x="200" y="96" font-size="10.5" fill="#334155">• Sözlük anlamı: "Gönül</text>\n  <text x="200" y="112" font-size="10.5" fill="#334155">  alma, uzlaştırıp kazanma"</text>\n  <text x="200" y="136" font-size="10.5" fill="#334155">• Fethedilen yer halkının</text>\n  <text x="200" y="152" font-size="10.5" fill="#334155">  din, dil, can ve mal</text>\n  <text x="200" y="168" font-size="10.5" fill="#334155">  güvenliğini koruma</text>\n  <text x="200" y="184" font-size="10.5" fill="#334155">• Vergide adalet ve kolaylık</text>\n  <text x="265" y="216" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#166534">Kalıcı Fetihlerin Sırrı!</text>\n  <rect x="354" y="48" width="155" height="190" rx="8" fill="#fefce8" stroke="#eab308"/>\n  <text x="431" y="72" text-anchor="middle" font-size="12" font-weight="bold" fill="#a16207">3. İskân (Yerleştirme)</text>\n  <text x="366" y="96" font-size="10.5" fill="#334155">• Balkanlar\'da fethedilen</text>\n  <text x="366" y="112" font-size="10.5" fill="#334155">  topraklara Anadolu\'dan</text>\n  <text x="366" y="128" font-size="10.5" fill="#334155">  konargöçer Türkmenleri</text>\n  <text x="366" y="144" font-size="10.5" fill="#334155">  planlı biçimde yerleştirme</text>\n  <text x="366" y="168" font-size="10.5" fill="#334155">• Cami, medrese, han ve</text>\n  <text x="366" y="184" font-size="10.5" fill="#334155">  köprülerle imar (şenlendirme)</text>\n  <text x="431" y="216" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#92400e">Balkanların Türkleşmesi</text>\n  <rect x="520" y="48" width="158" height="190" rx="8" fill="#fdf2f8" stroke="#ec4899"/>\n  <text x="599" y="72" text-anchor="middle" font-size="12" font-weight="bold" fill="#be185d">4. Millet Sistemi</text>\n  <text x="532" y="96" font-size="10.5" fill="#334155">• Toplumu ırka göre değil,</text>\n  <text x="532" y="112" font-size="10.5" fill="#334155">  DİN ve İNANÇ esasına</text>\n  <text x="532" y="128" font-size="10.5" fill="#334155">  göre yönetme sistemi</text>\n  <text x="532" y="152" font-size="10.5" fill="#334155">• Fatih\'in Bosna Fermanı</text>\n  <text x="532" y="168" font-size="10.5" fill="#334155">  (Ahidname-i Hümayun) ve</text>\n  <text x="532" y="184" font-size="10.5" fill="#334155">  Ortodoks/Ermeni patrikliği</text>\n  <text x="599" y="216" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#9d174d">Çok Kültürlü Barış (Pax Ottomana)</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">ANADOLU TÜRK SİYASİ BİRLİĞİ VE DOĞU-GÜNEY SİYASETİ</text>\n  <rect x="28" y="48" width="310" height="190" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="183" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">1. Anadolu Türk Siyasi Birliği</text>\n  <text x="44" y="98" font-size="11" fill="#334155">• Barışçıl Yollar: Karesioğulları (denizcilik),</text>\n  <text x="44" y="114" font-size="11" fill="#334155">  Germiyanoğulları (çeyiz) ve Hamitoğulları</text>\n  <text x="44" y="130" font-size="11" fill="#334155">  (toprak satın alma) ile büyüme</text>\n  <text x="44" y="154" font-size="11" fill="#334155">• Fatih Dönemi: Candaroğulları, Trabzon,</text>\n  <text x="44" y="170" font-size="11" fill="#334155">  Karamanoğulları ve Otlukbeli Zaferi (1473)</text>\n  <text x="44" y="194" font-size="11" font-weight="bold" fill="#1e40af">• Yavuz Dönemi: Turnadağ Savaşı (1515)</text>\n  <text x="44" y="210" font-size="10.5" fill="#1e40af">  (Dulkadiroğulları → Siyasi birlik kesinleşti!)</text>\n  <rect x="362" y="48" width="310" height="190" rx="8" fill="#fefce8" stroke="#eab308"/>\n  <text x="517" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#a16207">2. Yavuz ve Kanuni Dönemi Zirvesi</text>\n  <text x="378" y="98" font-size="11" fill="#334155">• Çaldıran (1514): Doğu Anadolu güvenliği</text>\n  <text x="378" y="120" font-size="11" fill="#334155">• Mercidabık (1516) ve Ridaniye (1517):</text>\n  <text x="378" y="136" font-size="11" fill="#334155">  Suriye, Filistin, Mısır ve Hicaz\'ın fethi;</text>\n  <text x="378" y="152" font-size="11" fill="#334155">  Halifelik ve Baharat Yolu Osmanlı\'ya geçti</text>\n  <text x="378" y="176" font-size="11" fill="#334155">• Kanuni Dönemi: Belgrad (1521), Mohaç</text>\n  <text x="378" y="192" font-size="11" fill="#334155">  Meydan Muharebesi (1526 - Macaristan) ve</text>\n  <text x="378" y="208" font-size="11" font-weight="bold" fill="#92400e">  I. Viyana Kuşatması (1529 - Orta Avrupa)</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">DENİZLERDE HÂKİMİYET: KARADENİZ VE AKDENİZ\'İN TÜRK GÖLÜ OLUŞU</text>\n  <rect x="28" y="48" width="310" height="190" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="183" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">1. Karadeniz Hâkimiyeti ve İpek Yolu</text>\n  <text x="44" y="98" font-size="11" fill="#334155">• Fatih Sultan Mehmed Dönemi:</text>\n  <text x="44" y="116" font-size="11" fill="#334155">  - Amasra (1459), Sinop ve Trabzon\'un (1461)</text>\n  <text x="44" y="132" font-size="11" fill="#334155">    alınmasıyla güney kıyıları birleşti.</text>\n  <text x="44" y="156" font-size="11" fill="#334155">  - Kırım\'ın Fethi (1475 - Gedik Ahmed Paşa):</text>\n  <text x="44" y="174" font-size="11" font-weight="bold" fill="#1e40af">    Karadeniz "Türk Gölü" hâline geldi ve</text>\n  <text x="44" y="190" font-size="11" font-weight="bold" fill="#1e40af">    İpek Yolu\'nun kuzey kolu denetime girdi.</text>\n  <rect x="362" y="48" width="310" height="190" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="517" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">2. Akdeniz Hâkimiyeti (Kanuni Dönemi)</text>\n  <text x="378" y="98" font-size="11" fill="#334155">• Rodos\'un Fethi (1522): Doğu Akdeniz güvenliği</text>\n  <text x="378" y="120" font-size="11" fill="#334155">• Cezayir\'in Katılması (1533): Barbaros</text>\n  <text x="378" y="136" font-size="11" fill="#334155">  Hayreddin Paşa Kaptan-ı Derya oldu.</text>\n  <text x="378" y="158" font-size="11" font-weight="bold" fill="#166534">• Preveze Deniz Zaferi (28 Eylül 1538):</text>\n  <text x="378" y="174" font-size="11" fill="#334155">  Haçlı donanması yenildi → Akdeniz Türk Gölü!</text>\n  <text x="378" y="196" font-size="11" fill="#334155">• Trablusgarp (1551), Cerbe (1560) ve</text>\n  <text x="378" y="212" font-size="11" font-weight="bold" fill="#15803d">  Kıbrıs\'ın Fethi (1571 - II. Selim dönemi)</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
